def purchase(request, db, payments):
    account = db.accounts.get(request.json['account_id'])
    charge = payments.capture(account.card, request.json['amount'])
    db.orders.insert(account_id=account.id, charge_id=charge.id)
    return {'charge_id': charge.id}

class Worker:
    def __init__(self, connect, schedule):
        self.connect = connect
        self.schedule = schedule
        self.stopped = False
        self.socket = None
    def reconnect(self):
        self.socket = self.connect()
        self.schedule(1, self.reconnect)
    def stop(self):
        self.stopped = True
        if self.socket:
            self.socket.close()

import { useEffect, useRef, useState } from 'react';
export function SearchPanel({ query, lookup }) {
  const [rows, setRows] = useState([]);
  const list = useRef(null);
  useEffect(() => {
    lookup(query).then(result => {
      setRows(result);
      list.current.scrollTop = list.current.scrollHeight;
      list.current.focus();
    });
  }, [query, lookup]);
  return <ul ref={list} tabIndex={0}>{rows.map(row => <li key={row.id}>{row.name}</li>)}</ul>;
}

type RoleRequest = { memberId: string; role: 'reader' | 'admin' };
export async function setRole(request: Request, identity: { memberId: string }, directory: Directory) {
  const body = (await request.json()) as RoleRequest;
  directory.setRole(body.memberId, body.role);
  return new Response('ok');
}

def final_price(subtotal, member):
    discount = subtotal * 0.10 if member else 0
    return round((subtotal - discount) * 1.20, 2)

def invoice_price(subtotal, member):
    tax = subtotal * 0.20
    discount = (subtotal + tax) * 0.15 if member else 0
    return round(subtotal + tax - discount, 2)

